package com.minhnb.finvera_be.alert.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="alert_delivery_attempt")public class AlertDeliveryAttemptEntity{@Id private UUID id;@Column(name="notification_id")private UUID notificationId;private String channel;@Column(name="attempt_no")private short attemptNo;private String outcome;@Column(name="reason_code")private String reasonCode;@Column(name="attempted_at")private Instant attemptedAt;@Column(name="completed_at")private Instant completedAt;protected AlertDeliveryAttemptEntity(){}public AlertDeliveryAttemptEntity(UUID id,UUID n,Instant at){this.id=id;notificationId=n;channel="IN_APP";attemptNo=1;outcome="DELIVERED";attemptedAt=at;completedAt=at;}}
